// Exact sparse one-variable leading coefficient certificate over Z_(32003).
// Row/column completions have p-integral coefficients and determinant p-unit.
#include <flint/fmpq_mpoly.h>
#include <flint/fmpq_mat.h>
#include <flint/fmpz.h>
#include <cassert>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <chrono>
#include <algorithm>
using namespace std;
fmpq_mpoly_ctx_t ctx; const long prime=32003;
struct Poly { fmpq_mpoly_t p; Poly(){fmpq_mpoly_init(p,ctx);} Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);} Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);} Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;} ~Poly(){fmpq_mpoly_clear(p,ctx);} };
long power(long a,long e){long z=1;for(;e;e>>=1,a=a*a%prime)if(e&1)z=z*a%prime;return z;}
long residue(const fmpq_t q){long den=fmpz_fdiv_ui(fmpq_denref(q),prime);assert(den);return fmpz_fdiv_ui(fmpq_numref(q),prime)*power(den,prime-2)%prime;}
void read(istream&in,Poly&p){long nn;in>>nn;fmpq_t q;fmpq_init(q);ulong exp[1];for(long z=0;z<nn;z++){string c;in>>c>>exp[0];assert(!fmpq_set_str(q,c.c_str(),10));fmpq_canonicalise(q);residue(q);fmpq_mpoly_push_term_fmpq_ui(p.p,q,exp,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);fmpq_clear(q);}
ulong valuation(const Poly&p){long nn=fmpq_mpoly_length(p.p,ctx);if(!nn)return ULONG_MAX;ulong exp[1];fmpq_mpoly_get_term_exp_ui(exp,p.p,nn-1,ctx);return exp[0];}
void shift(Poly&p,ulong v){if(!v||fmpq_mpoly_is_zero(p.p,ctx))return;Poly z;ulong exp[1];fmpq_t q;fmpq_init(q);for(long k=0;k<fmpq_mpoly_length(p.p,ctx);k++){fmpq_mpoly_get_term_exp_ui(exp,p.p,k,ctx);assert(exp[0]>=v);exp[0]-=v;fmpq_mpoly_get_term_coeff_fmpq(q,p.p,k,ctx);fmpq_mpoly_push_term_fmpq_ui(z.p,q,exp,ctx);}fmpq_mpoly_sort_terms(z.p,ctx);fmpq_mpoly_combine_like_terms(z.p,ctx);p=std::move(z);fmpq_clear(q);}
int profile(const fmpq_mat_t L,vector<int>&rr,vector<int>&cc){int n=fmpq_mat_nrows(L),rank=0;vector<vector<long>>a(n,vector<long>(n));vector<int>ids(n);for(int i=0;i<n;i++){ids[i]=i;for(int j=0;j<n;j++)a[i][j]=residue(fmpq_mat_entry(L,i,j));}for(int c=0;c<n;c++){int r=rank;while(r<n&&!a[r][c])r++;if(r==n)continue;swap(a[r],a[rank]);swap(ids[r],ids[rank]);rr.push_back(ids[rank]);cc.push_back(c);long inv=power(a[rank][c],prime-2);for(int j=c;j<n;j++)a[rank][j]=a[rank][j]*inv%prime;for(int i=rank+1;i<n;i++){long t=a[i][c];if(!t)continue;for(int j=c;j<n;j++)a[i][j]=(a[i][j]-t*a[rank][j]%prime+prime)%prime;}rank++;}return rank;}
long moddet(const fmpq_mat_t L){int n=fmpq_mat_nrows(L);vector<vector<long>>a(n,vector<long>(n));for(int i=0;i<n;i++)for(int j=0;j<n;j++)a[i][j]=residue(fmpq_mat_entry(L,i,j));long det=1;for(int c=0;c<n;c++){int r=c;while(r<n&&!a[r][c])r++;if(r==n)return 0;if(r!=c){swap(a[r],a[c]);det=(prime-det)%prime;}long p=a[c][c],inv=power(p,prime-2);det=det*p%prime;for(int i=c+1;i<n;i++){long t=a[i][c]*inv%prime;for(int j=c;j<n;j++)a[i][j]=(a[i][j]-t*a[c][j]%prime+prime)%prime;}}return det;}
int main(int argc,char**argv){assert(argc==4);ifstream in(argv[1]);ofstream out(argv[2]);assert(in&&out);double limit=stod(argv[3]);auto start=chrono::steady_clock::now();fmpq_mpoly_ctx_init(ctx,1,ORD_LEX);{int n;in>>n;vector<vector<Poly>> A(n,vector<Poly>(n));for(auto&r:A)for(auto&p:r)read(in,p);assert(in.good());ulong val=0;fmpq_t q,scale;fmpq_init(q);fmpq_init(scale);out<<"PRIME "<<prime<<" SIZE "<<n<<'\n';for(int stage=0;stage<300;stage++){ulong gained=0;for(int i=0;i<n;i++){ulong v=ULONG_MAX;for(int c=0;c<n;c++)v=min(v,valuation(A[i][c]));assert(v!=ULONG_MAX);if(v){for(int c=0;c<n;c++)shift(A[i][c],v);gained+=v;out<<"ROW_SHIFT "<<stage<<' '<<i<<' '<<v<<'\n';}}for(int c=0;c<n;c++){ulong v=ULONG_MAX;for(int i=0;i<n;i++)v=min(v,valuation(A[i][c]));assert(v!=ULONG_MAX);if(v){for(int i=0;i<n;i++)shift(A[i][c],v);gained+=v;out<<"SHIFT "<<stage<<' '<<c<<' '<<v<<'\n';}}val+=gained;
// Scale only by p-units; this preserves V-integrality and unit leading coefficients.
for(int c=0;c<n;c++){bool found=false;for(int i=0;i<n&&!found;i++)for(long k=0;k<fmpq_mpoly_length(A[i][c].p,ctx);k++){fmpq_mpoly_get_term_coeff_fmpq(q,A[i][c].p,k,ctx);if(residue(q)){fmpq_set(scale,q);found=true;break;}}assert(found);for(int i=0;i<n;i++)fmpq_mpoly_scalar_div_fmpq(A[i][c].p,A[i][c].p,scale,ctx);}
fmpq_mat_t L;fmpq_mat_init(L,n,n);ulong zero[1]={0};long terms=0;for(int i=0;i<n;i++)for(int j=0;j<n;j++){fmpq_mpoly_get_coeff_fmpq_ui(fmpq_mat_entry(L,i,j),A[i][j].p,zero,ctx);terms+=fmpq_mpoly_length(A[i][j].p,ctx);}vector<int>rr,cc;int r=profile(L,rr,cc),k=n-r;double sec=chrono::duration<double>(chrono::steady_clock::now()-start).count();cerr<<"STAGE "<<stage<<" RANK "<<r<<" CORANK "<<k<<" VAL "<<val<<" GAIN "<<gained<<" TERMS "<<terms<<" SEC "<<sec<<'\n';out<<"STAGE "<<stage<<" RANK "<<r<<" CORANK "<<k<<" VAL "<<val<<" GAIN "<<gained<<" TERMS "<<terms<<'\n';out.flush();if(r==n){long det=moddet(L);assert(det);out<<"PASS LEADING_P_UNIT "<<det<<" VALUATION "<<val<<" SECONDS "<<sec<<'\n';cerr<<"PASS LEADING_P_UNIT "<<det<<" VALUATION "<<val<<'\n';fmpq_mat_clear(L);break;}if(sec>limit||terms>4000000){out<<"BOUNDED_STOP\n";fmpq_mat_clear(L);return 2;}assert(r>0);vector<int>free;for(int j=0;j<n;j++)if(find(cc.begin(),cc.end(),j)==cc.end())free.push_back(j);fmpq_mat_t P,Inv,C,B,K,Z;fmpq_mat_init(P,r,r);fmpq_mat_init(Inv,r,r);fmpq_mat_init(C,r,k);fmpq_mat_init(B,r,k);fmpq_mat_init(K,n,k);fmpq_mat_init(Z,n,k);for(int i=0;i<r;i++){for(int j=0;j<r;j++)fmpq_set(fmpq_mat_entry(P,i,j),fmpq_mat_entry(L,rr[i],cc[j]));for(int j=0;j<k;j++)fmpq_set(fmpq_mat_entry(C,i,j),fmpq_mat_entry(L,rr[i],free[j]));}assert(fmpq_mat_inv(Inv,P));fmpq_mat_mul(B,Inv,C);for(int j=0;j<k;j++){fmpq_one(fmpq_mat_entry(K,free[j],j));for(int i=0;i<r;i++){fmpq_neg(fmpq_mat_entry(K,cc[i],j),fmpq_mat_entry(B,i,j));residue(fmpq_mat_entry(K,cc[i],j));}}fmpq_mat_mul(Z,L,K);if(!fmpq_mat_is_zero(Z)){out<<"BAD_PRIME_RANK_DROP\n";cerr<<"BAD_PRIME_RANK_DROP\n";return 3;}out<<"PIVOT_COLS "<<r;for(int c:cc)out<<' '<<c;out<<"\nKERNEL "<<n<<' '<<k<<'\n';for(int j=0;j<k;j++){for(int i=0;i<n;i++){char*s=fmpq_get_str(nullptr,10,fmpq_mat_entry(K,i,j));out<<s<<' ';flint_free(s);}out<<'\n';}out.flush();vector<vector<Poly>> Next(n,vector<Poly>(n));Poly tmp;for(int i=0;i<n;i++){for(int j=0;j<r;j++)Next[i][j]=A[i][cc[j]];for(int j=0;j<k;j++)for(int c=0;c<n;c++)if(!fmpq_is_zero(fmpq_mat_entry(K,c,j))&&!fmpq_mpoly_is_zero(A[i][c].p,ctx)){fmpq_mpoly_scalar_mul_fmpq(tmp.p,A[i][c].p,fmpq_mat_entry(K,c,j),ctx);fmpq_mpoly_add(Next[i][r+j].p,Next[i][r+j].p,tmp.p,ctx);}for(int j=r;j<n;j++)assert(valuation(Next[i][j])>0);}// Exact p-integral row-completion kills all leading entries in complementary rows.
vector<int>fr;for(int i=0;i<n;i++)if(find(rr.begin(),rr.end(),i)==rr.end())fr.push_back(i);
fmpq_mat_t D,E;fmpq_mat_init(D,k,r);fmpq_mat_init(E,k,r);
for(int i=0;i<k;i++)for(int j=0;j<r;j++)fmpq_set(fmpq_mat_entry(D,i,j),fmpq_mat_entry(L,fr[i],cc[j]));
fmpq_mat_mul(E,D,Inv);for(int i=0;i<k;i++)for(int j=0;j<r;j++)residue(fmpq_mat_entry(E,i,j));
vector<vector<Poly>> Final(n,vector<Poly>(n));
for(int i=0;i<r;i++)for(int j=0;j<n;j++)Final[i][j]=Next[rr[i]][j];
for(int i=0;i<k;i++)for(int j=0;j<n;j++){Final[r+i][j]=Next[fr[i]][j];for(int h=0;h<r;h++)if(!fmpq_is_zero(fmpq_mat_entry(E,i,h))&&!fmpq_mpoly_is_zero(Next[rr[h]][j].p,ctx)){fmpq_mpoly_scalar_mul_fmpq(tmp.p,Next[rr[h]][j].p,fmpq_mat_entry(E,i,h),ctx);fmpq_mpoly_sub(Final[r+i][j].p,Final[r+i][j].p,tmp.p,ctx);}assert(valuation(Final[r+i][j])>0);}
out<<"ROW_PIVOTS "<<r;for(int i:rr)out<<' '<<i;out<<"\nROW_COMPLETION "<<k<<' '<<r<<'\n';for(int i=0;i<k;i++){for(int j=0;j<r;j++){char*s=fmpq_get_str(nullptr,10,fmpq_mat_entry(E,i,j));out<<s<<' ';flint_free(s);}out<<'\n';}out.flush();
A=std::move(Final);fmpq_mat_clear(D);fmpq_mat_clear(E);fmpq_mat_clear(P);fmpq_mat_clear(Inv);fmpq_mat_clear(C);fmpq_mat_clear(B);fmpq_mat_clear(K);fmpq_mat_clear(Z);fmpq_mat_clear(L);}fmpq_clear(q);fmpq_clear(scale);out.flush();assert(out.good());}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
